using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Microsoft.CodeAnalysis;using Microsoft.CodeAnalysis.CSharp;
public class VerifyArmory083 {public static string Main(){AssetDatabase.Refresh();string[] paths={"Assets/Prefabs/Workshop/Services/Supplies_Wooden_01.prefab","Assets/Prefabs/Workshop/Fisher/Fisher_Empty_01.prefab","Assets/Prefabs/Workshop/Services/LootTrader_Wooden_01.prefab","Assets/Prefabs/Workshop/Armory/Armory_Wooden_01.prefab","Assets/Prefabs/Workshop/Sheriff/Sheriff_Stone_Compact_01.prefab","Assets/Prefabs/Workshop/Hospital/Hospital_Stone_01.prefab","Assets/Prefabs/Workshop/CastleServices/CastleServices_01.prefab"};foreach(var p in paths)if(AssetDatabase.LoadAssetAtPath<GameObject>(p)==null)throw new Exception("Import failed "+p);var syntax=CSharpSyntaxTree.ParseText(File.ReadAllText("Assets/Scripts/ItemStore.cs"));if(syntax.GetDiagnostics().Any(d=>d.Severity==DiagnosticSeverity.Error))throw new Exception("Syntax errors");
 string stub=@"namespace UnityEngine { public class SerializeField:System.Attribute {} public class MonoBehaviour {} public class Collider {public string tag;} public class Transform {public StorePoint[] points;public T[] GetComponentsInChildren<T>(){return (T[])(object)points;}} public static class Random {public static int Range(int min,int max){return max-1;}} } public class PickableItem {public string name;public PickableItem(string n){name=n;}} public class StoreItemsCollection {public System.Collections.Generic.List<PickableItem> Items;} public class StorePoint {public bool StaticItem;public string picked;public void InitPoint(bool lobby,ItemStore store,PickableItem item=null){picked=item==null?null:item.name;}} public static class AssortmentProbe {public static string Run(bool lobby,string[] names){var store=new ItemStore();var pts=new[]{new StorePoint(),new StorePoint(),new StorePoint(),new StorePoint()};var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;typeof(ItemStore).GetField(""_pointsParent"",flags).SetValue(store,new UnityEngine.Transform{points=pts});typeof(ItemStore).GetField(""_collection"",flags).SetValue(store,new StoreItemsCollection{Items=System.Linq.Enumerable.ToList(System.Linq.Enumerable.Select(names,n=>new PickableItem(n)))});typeof(ItemStore).GetField(""_inLobby"",flags).SetValue(store,lobby);typeof(ItemStore).GetMethod(""Start"",flags).Invoke(store,null);return string.Join("","",System.Linq.Enumerable.Select(pts,p=>p.picked));}}";
 var refs=AppDomain.CurrentDomain.GetAssemblies().Where(a=>!a.IsDynamic&&!string.IsNullOrEmpty(a.Location)).Select(a=>MetadataReference.CreateFromFile(a.Location));var comp=CSharpCompilation.Create("ArmoryAssortmentProbe083",new[]{syntax,CSharpSyntaxTree.ParseText(stub)},refs,new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));string check;using(var ms=new MemoryStream()){var emit=comp.Emit(ms);if(!emit.Success)throw new Exception(string.Join("\n",emit.Diagnostics.Where(d=>d.Severity==DiagnosticSeverity.Error)));var asm=System.Reflection.Assembly.Load(ms.ToArray());var run=asm.GetType("AssortmentProbe").GetMethod("Run");string[] actual={"Pistol","Shotgun","Rifle","AmmoMusket","AmmoRifle","AmmoShotgun"};var fixedResult=(string)run.Invoke(null,new object[]{false,actual});var lobbyResult=(string)run.Invoke(null,new object[]{true,actual});var other=(string)run.Invoke(null,new object[]{false,new[]{"A","B","C","D"}});if(fixedResult!="Pistol,Rifle,Shotgun,AmmoMusket"||lobbyResult!="AmmoShotgun,AmmoRifle,AmmoMusket,Rifle"||other!="D,C,B,A")throw new Exception("Assortment mismatch "+fixedResult+" / "+lobbyResult+" / "+other);check="Actual ItemStore.Start compiled with dependency stubs: six-item GunStore yields Pistol,Rifle,Shotgun,AmmoMusket; lobby and unrelated assortment retain random selection. Full Unity/game integration still untested.";}
 var sc=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(sc.isDirty)EditorSceneManager.SaveScene(sc);if(sc.isDirty)throw new Exception("Scene remains dirty");File.AppendAllText("Docs/assets/examples/ARMORY_EXTENSION_VALIDATION.txt",check+"\nPASS: seven prefabs imported; scene IsDirty=false.\n");return check+" Prefab import and saved scene PASS.";}}
